package com.tarapickle.identity.domain; import com.tarapickle.identity.domain.model.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
class UserSessionTest {@Test void rotatesAndRevokes(){Instant now=Instant.parse("2026-08-21T10:00:00Z");UserSession s=new UserSession(UUID.randomUUID(),UUID.randomUUID(),"old",now,now.plusSeconds(60),"test", "127.0.0.1");s.rotate("new",now.plusSeconds(1));assertThat(s.getPreviousTokenHash()).isEqualTo("old");assertThat(s.getRefreshTokenHash()).isEqualTo("new");s.revoke(now.plusSeconds(2));assertThat(s.active(now.plusSeconds(3))).isFalse();}}
